    try { await handle.writeFile(buffer); try { await handle.sync(); } catch (_) {} }
    finally { await handle.close(); }
    await replaceFileWithRetry(temporary, file);
  } finally { try { await fsp.unlink(temporary); } catch (_) {} }
}

